add('thm-qc-finite-naimark-isometric-compression','theorem','QC04','For a finite complete effect family E_a on H, the map Vx=sum_a sqrt(E_a)x tensor |a> into H tensor C^m is an isometry, and E_a=V†(I tensor |a><a|)V. Thus each finite POVM has a finite projective compression with exactly the same outcome law; no physical realization is asserted.',['def-qc-povm-and-outcome-law','thm-non-negative-square-root-exists-and-is-unique','def-qc-tensor-map','def-qc-dirac-notation-conversion'],['V†V=sum E_a=I by orthogonal labels and sqrt(E_a)²=E_a. Compress each label projector directly to E_a; cycle finite traces to identify probabilities.'],locator='Chapter 2 measurements and Naimark dilation; local finite isometric proof')
edit('def-qc-finite-outcome-probability-kernel',s='Equip the finite-dimensional density set with its matrix-coordinate Borel sigma algebra and the finite outcome set with all subsets. Define the kernel K(rho,{a})=tr(rho E_a), extending to subsets by finite sums.',proof=['The coordinates are continuous linear trace functionals and hence Borel measurable in rho; normalization/positivity are discharged by its theorem. A finite discrete outcome sigma algebra alone does not prove input measurability.'])
